// typedPlaceholder returns the placeholder token for a recognized pattern.
func typedPlaceholder(s string) string {
	if isUUID(s) {
		return "<UUID>"
	}
	if isIP(s) {
		return "<IP>"
	}
	if isHex(s) {
		return "<HEX>"
	}
	if isNum(s) {
		return "<NUM>"
	}
	if isPath(s) {
		return "<PATH>"
	}
	return ""
}

// isNum reports whether s looks like an integer or decimal number.
func isNum(s string) bool {
	if len(s) == 0 {
		return false
	}
	dotSeen := false
	for _, c := range s {
		switch {
		case c >= '0' && c <= '9':
			continue
		case c == '.' && !dotSeen:
			dotSeen = true
		case c == '-' && len(s) > 1 && s[0] == '-':
			continue
		default:
			return false
		}
	}
	return true
}

// isUUID reports whether s matches the canonical UUID format.
func isUUID(s string) bool {
	if len(s) != 36 {
		return false
	}
	uuidRe := regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)
	return uuidRe.MatchString(s)
}

// isIP reports whether s looks like an IPv4 address.
func isIP(s string) bool {
	parts := splitRune(s, '.')
	if len(parts) != 4 {
		return false
	}
	for _, p := range parts {
		if !isNum(p) {
			return false
		}
		n := atoi(p)
		if n < 0 || n > 255 {
			return false
		}
	}
	return true
}

// isHex reports whether s is a hex string of length >= 8 (no leading 0x).
func isHex(s string) bool {
	if len(s) < 8 {
		return false
	}
	hexRe := regexp.MustCompile(`^[0-9a-fA-F]+$`)
	return hexRe.MatchString(s)
}

// isPath reports whether s looks like a filesystem path (starts with / or .).
func isPath(s string) bool {
	if len(s) == 0 {
		return false
	}
	return s[0] == '/' || (len(s) >= 2 && s[0] == '.' && s[1] == '/')
}

// MaskLine replaces variable tokens in a log line with typed placeholders.
func MaskLine(line string) string {
	tokens := tokenize(line)
	var result []string
	for _, tok := range tokens {
		if ph := typedPlaceholder(tok); ph != "" {
			result = append(result, ph)
		} else {
			result = append(result, tok)
		}
	}
	return joinTokens(result)
}

// tokenize splits a line on whitespace into tokens.
func tokenize(line string) []string {
	var tokens []string
	var cur []rune
	for _, r := range line {
		switch {
		case r == ' ' || r == '\t':
			if len(cur) > 0 {
				tokens = append(tokens, string(cur))
				cur = cur[:0]
			}
		default:
			cur = append(cur, r)
		}
	}
	if len(cur) > 0 {
		tokens = append(tokens, string(cur))
	}
	return tokens
}

// joinTokens joins tokens back with single spaces.
func joinTokens(tokens []string) string {
	var result []byte
	for i, tok := range tokens {
		if i > 0 {
			result = append(result, ' ')
		}
		result = append(result, tok...)
	}
	return string(result)
}

func lineFromTokens(tokens []string) int {
	l := 0
	for _, t := range tokens {
		l += len(t) + 1
	}
	return l
}

func splitRune(s string, sep rune) []string {
	var parts []string
	var cur []rune
	for _, r := range s {
		if r == sep {
			parts = append(parts, string(cur))
			cur = cur[:0]
		} else {
			cur = append(cur, r)
		}
	}
	parts = append(parts, string(cur))
	return parts
}

func atoi(s string) int {
	var n int
	for _, c := range s {
		if c >= '0' && c <= '9' {
			n = n*10 + int(c-'0')
		}
	}
	return n
}

package miner

// Diff compares two sets of LogGroups and returns NEW, GONE, and SHIFTED entries.
// Identity is a strict hash of the exact token sequence; <*> at any position breaks equality.
func Diff(baseline, current []LogGroup) (newT, goneT, shiftedT []DiffEntry) {
	bMap := make(map[string]*LogGroup)
	for _, g := range baseline {
		h := templateHash(g.Template)
		bMap[h] = &g
	}

	cMap := make(map[string]*LogGroup)
	for _, g := range current {
		h := templateHash(g.Template)
		cMap[h] = &g
	}

	// NEW: in current but not baseline
	for h, cg := range cMap {
		if _, ok := bMap[h]; !ok {
			newT = append(newT, DiffEntry{
				Template:  cg.Template,
				Count:     cg.Count,
				Example:   cg.Example,
				FirstLine: cg.FirstLine,
				LastLine:  cg.LastLine,
			})
		}
	}

	// GONE: in baseline but not current
	for h, bg := range bMap {
		if _, ok := cMap[h]; !ok {
			goneT = append(goneT, DiffEntry{
				Template:  bg.Template,
				Count:     bg.Count,
				Example:   bg.Example,
				FirstLine: bg.FirstLine,
				LastLine:  bg.LastLine,
			})
		}
	}

	// SHIFTED: in both but count changed
	for h, bg := range bMap {
		cg, ok := cMap[h]
		if !ok {
			continue
		}
		if bg.Count != cg.Count {
			shiftedT = append(shiftedT, DiffEntry{
				Template:      bg.Template,
				BaselineCount: bg.Count,
				NewCount:      cg.Count,
			})
		}
	}

	return newT, goneT, shiftedT
}

package miner

import (
	"sort"
)

// GroupByTemplate groups folded lines by their masked template.
// It returns a slice of LogGroup sorted by count descending.
func GroupByTemplate(lines []FoldedLine, depth int) []LogGroup {
	tree := NewTreeFunc(depth)
	for _, fl := range lines {
		masked := MaskLine(fl.Text)
		tree.Insert(masked, fl.Text, int64(fl.LineNum))
	}
	return tree.Collect()
}

// FoldedLine is an alias for the reader's type so we can group without importing io.
type FoldedLine struct {
	Text    string
	LineNum int
}

// SortByCount sorts groups by count descending (in place).
func SortByCount(groups []LogGroup) {
	sort.Slice(groups, func(i, j int) bool {
		return groups[i].Count > groups[j].Count
	})
}

