package io

import (
	"bufio"
	"io"
	"os"
	"strings"
)

// FoldedLine is a logical log record: one physical line or a stack trace
// folded into a single record. LineNum is the first physical line number.
type FoldedLine struct {
	Text    string
	LineNum int // first physical line number of the logical record
}

// Reader wraps an io.Reader and folds indented continuation lines (e.g. stack
// traces) into a single logical record, tracking the originating line number.
type Reader struct {
	scanner  *bufio.Scanner
	r        io.Reader
	closer   io.Closer
	firstNum int
	lineNum  int
	buf      strings.Builder
}

// NewReader creates a Reader from any io.Reader. If r implements io.Closer,
// Close will delegate to it.
func NewReader(r io.Reader) *Reader {
	var closer io.Closer
	if c, ok := r.(io.Closer); ok {
		closer = c
	}
	return &Reader{
		scanner: bufio.NewScanner(r),
		r:       r,
		closer:  closer,
	}
}

// OpenFile returns a Reader reading from the named file.
func OpenFile(path string) (*Reader, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	return &Reader{
		scanner: bufio.NewScanner(f),
		r:       f,
		closer:  f,
	}, nil
}

// ReadStdin returns a Reader reading from standard input.
func ReadStdin() (*Reader, error) {
	return &Reader{
		scanner: bufio.NewScanner(os.Stdin),
		r:       os.Stdin,
	}, nil
}

// Close releases any underlying resource (file handle, etc.).
func (r *Reader) Close() error {
	if r.closer != nil {
		return r.closer.Close()
	}
	return nil
}

// isContinuation reports whether a physical line should be folded into the
// preceding logical record.  A line is a continuation if it:
//   - begins with whitespace (tab or space), OR
//   - matches common stack-frame prefixes: "at ", "Caused by"
func isContinuation(line string) bool {
	if len(line) == 0 {
		return false
	}
	if line[0] == ' ' || line[0] == '\t' {
		return true
	}
	// Java stack-frame prefix without leading whitespace.
	if strings.HasPrefix(line, "at ") {
		return true
	}
	// Java multi-cause marker.
	if strings.HasPrefix(line, "Caused by") {
		return true
	}
	return false
}

// Next returns the next folded logical line.  It scans physical lines from
// the underlying reader, folding continuations into the current record until
// a non-continuation line or EOF is reached.  Returns io.EOF when no more
// records are available.
func (r *Reader) Next() (FoldedLine, error) {
	for r.scanner.Scan() {
		r.lineNum++
		line := r.scanner.Text()

		if r.firstNum == 0 {
			// Start of a new logical record.
			r.firstNum = r.lineNum
			r.buf.WriteString(line)
			continue
		}

		if isContinuation(line) {
			// Fold into the current logical record.
			r.buf.WriteByte('\n')
			r.buf.WriteString(line)
			continue
		}

		// Non-continuation: return what we have, start a new record.
		result := FoldedLine{Text: r.buf.String(), LineNum: r.firstNum}
		r.firstNum = r.lineNum
		r.buf.Reset()
		r.buf.WriteString(line)
		return result, nil
	}

	if err := r.scanner.Err(); err != nil {
		return FoldedLine{}, err
	}

	// Return any remaining buffer.
	if r.buf.Len() > 0 {
		result := FoldedLine{Text: r.buf.String(), LineNum: r.firstNum}
		r.firstNum = 0
		r.buf.Reset()
		return result, nil
	}

	return FoldedLine{}, io.EOF
}

package format

import (
	"encoding/json"

	"allon/internal/miner"
)

// MineJSON is the JSON schema for mine output.
type MineJSON struct {
	TotalLines int64          `json:"total_lines"`
	Templates  []TemplateJSON `json:"templates"`
}

// TemplateJSON describes one log template in JSON output.
type TemplateJSON struct {
	ID        int    `json:"id"`
	Template  string `json:"template"`
	Count     int64  `json:"count"`
	Example   string `json:"example"`
	FirstLine int    `json:"first_line"`
	LastLine  int    `json:"last_line"`
}

// DiffJSON is the JSON schema for diff output.
type DiffJSON struct {
	New      []TemplateJSON `json:"new"`
	Gone     []TemplateJSON `json:"gone"`
	Shifted  []ShiftedJSON  `json:"shifted"`
	ExitCode int            `json:"exit_code"`
}

// ShiftedJSON describes a template whose count changed between baseline and new.
type ShiftedJSON struct {
	TemplateJSON
	BaselineCount int64   `json:"baseline_count"`
	NewCount      int64   `json:"new_count"`
	Ratio         float64 `json:"ratio"`
}

// MarshalMine converts log groups into indented JSON bytes.
func MarshalMine(groups []miner.LogGroup, totalLines int64) ([]byte, error) {
	templates := make([]TemplateJSON, 0, len(groups))
	for i, g := range groups {
		templates = append(templates, TemplateJSON{
			ID:        i + 1,
			Template:  g.Template,
			Count:     g.Count,
			Example:   g.Example,
			FirstLine: int(g.FirstLine),
			LastLine:  int(g.LastLine),
		})
	}
	return json.MarshalIndent(MineJSON{
		TotalLines: totalLines,
		Templates:  templates,
	}, "", "  ")
}

// MarshalDiff converts diff entries into indented JSON bytes.
func MarshalDiff(newT, goneT, shiftedT []miner.DiffEntry) ([]byte, error) {
	exitCode := 0
	if len(newT) > 0 || len(goneT) > 0 {
		exitCode = 1
	}

	toTemplateJSON := func(e miner.DiffEntry) TemplateJSON {
		return TemplateJSON{
			Template:  e.Template,
			Count:     e.Count,
			Example:   e.Example,
			FirstLine: int(e.FirstLine),
			LastLine:  int(e.LastLine),
		}
	}

	newJSON := make([]TemplateJSON, 0, len(newT))
	for _, e := range newT {
		tj := toTemplateJSON(e)
		newJSON = append(newJSON, tj)
	}

	goneJSON := make([]TemplateJSON, 0, len(goneT))
	for _, e := range goneT {
		tj := toTemplateJSON(e)
		goneJSON = append(goneJSON, tj)
	}

	shiftedJSON := make([]ShiftedJSON, 0, len(shiftedT))
	for _, e := range shiftedT {
		tj := toTemplateJSON(e)
		ratio := float64(0)
		if e.BaselineCount > 0 {
			ratio = float64(e.NewCount) / float64(e.BaselineCount)
		}
		shiftedJSON = append(shiftedJSON, ShiftedJSON{
			TemplateJSON:  tj,
			BaselineCount: e.BaselineCount,
			NewCount:      e.NewCount,
			Ratio:         ratio,
		})
	}

	return json.MarshalIndent(DiffJSON{
		New:      newJSON,
		Gone:     goneJSON,
		Shifted:  shiftedJSON,
		ExitCode: exitCode,
	}, "", "  ")
}

package format

import (
	"fmt"
	"io"
	"sort"
	"text/tabwriter"

	"allon/internal/miner"
)

// truncateTemplate shortens a template string to maxLen characters.
// If longer, it is truncated and suffixed with "…".
func truncateTemplate(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen] + "…"
}

// RenderMine writes a column-aligned table of log groups to w.
func RenderMine(groups []miner.LogGroup, w io.Writer) {
	if len(groups) == 0 {
		fmt.Fprintln(w, "No templates found")
		return
	}

	sorted := make([]miner.LogGroup, len(groups))
	copy(sorted, groups)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].Count > sorted[j].Count
	})

	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)

	fmt.Fprintf(tw, "TEMPLATE\tCOUNT\tFIRST\tLAST\tEXAMPLE\n")
	for _, g := range sorted {
		template := truncateTemplate(g.Template, 80)
		example := truncateTemplate(g.Example, 80)
		fmt.Fprintf(tw, "%s\t%8d\t%d\t%d\t%s\n", template, g.Count, g.FirstLine, g.LastLine, example)
	}
	tw.Flush()
}

// RenderDiff writes a column-aligned diff report to w with NEW, GONE, and SHIFTED sections.
func RenderDiff(newT, goneT, shiftedT []miner.DiffEntry, w io.Writer) {
	hasData := len(newT) > 0 || len(goneT) > 0 || len(shiftedT) > 0
	if !hasData {
		fmt.Fprintln(w, "No differences")
		return
	}

	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)

	printSection := func(label string, entries []miner.DiffEntry) {
		if len(entries) == 0 {
			return
		}
		sorted := make([]miner.DiffEntry, len(entries))
		copy(sorted, entries)
		sort.Slice(sorted, func(i, j int) bool {
			return sorted[i].Count > sorted[j].Count
		})

		fmt.Fprintf(tw, "\n%s\n---\n", label)
		fmt.Fprintf(tw, "TEMPLATE\tCOUNT\tFIRST\tLAST\tEXAMPLE\n")
		for _, e := range sorted {
			template := truncateTemplate(e.Template, 80)
			example := truncateTemplate(e.Example, 80)
			fmt.Fprintf(tw, "%s\t%8d\t%d\t%d\t%s\n", template, e.Count, e.FirstLine, e.LastLine, example)
		}
	}

	printSection("NEW", newT)
	printSection("GONE", goneT)
	if len(shiftedT) > 0 {
		sorted := make([]miner.DiffEntry, len(shiftedT))
		copy(sorted, shiftedT)
		sort.Slice(sorted, func(i, j int) bool {
			return sorted[i].Count > sorted[j].Count
		})

		fmt.Fprintf(tw, "\nSHIFTED\n---\n")
		fmt.Fprintf(tw, "TEMPLATE\tBASELINE\tNEW\tRATIO\n")
		for _, e := range sorted {
			template := truncateTemplate(e.Template, 80)
			ratio := float64(0)
			if e.BaselineCount > 0 {
				ratio = float64(e.NewCount) / float64(e.BaselineCount)
			}
			fmt.Fprintf(tw, "%s\t%8d\t%8d\t%.2f\n", template, e.BaselineCount, e.NewCount, ratio)
		}
	}
	tw.Flush()
}

package miner

import (
	"crypto/sha256"
	"fmt"
	"sort"
)

// templateHash returns a strict hash of the token sequence.
// <*> at any position breaks equality — no fuzzy matching.
func templateHash(template string) string {
	tokens := tokenize(template)
	h := sha256.New()
	for _, t := range tokens {
		fmt.Fprint(h, t)
	}
	return fmt.Sprintf("%x", h.Sum(nil))[:16]
}

// Tree is a fixed-depth trie that routes masked log lines to LogGroups.
type Tree struct {
	depth int
	root  *node
}

type node struct {
	children map[string]*node
	group    *LogGroup
}

func newNode() *node {
	return &node{children: make(map[string]*node)}
}

// NewTree creates a Tree with the given depth (number of fixed tokens to keep before wildcarding).
type NewTree struct {
	Depth int
}

// NewTreeFunc is the constructor.
func NewTreeFunc(depth int) *Tree {
	return &Tree{depth: depth, root: newNode()}
}

// Insert adds a masked line into the tree at the given depth.
// If depth >= 0, only the first `depth` tokens are kept; the rest become <*>.
func (t *Tree) Insert(masked string, example string, lineNum int64) {
	tokens := tokenize(masked)

	// Apply fixed-depth generalization: replace tokens beyond depth with <*>
	if t.depth >= 0 && len(tokens) > t.depth {
		tokens = append(append([]string{}, tokens[:t.depth]...), "<*>")
	}

	current := t.root
	for _, tok := range tokens {
		child, ok := current.children[tok]
		if !ok {
			child = newNode()
			current.children[tok] = child
		}
		current = child
	}

	template := joinTokens(tokens)
	if current.group == nil {
		current.group = &LogGroup{
			Template:  template,
			Count:     1,
			Example:   example,
			FirstLine: lineNum,
			LastLine:  lineNum,
		}
	} else {
		current.group.Count++
		current.group.LastLine = lineNum
	}
}

// Collect returns all LogGroups from the tree, sorted by count descending.
func (t *Tree) Collect() []LogGroup {
	var groups []LogGroup
	t.root.collect(&groups)
	sort.Slice(groups, func(i, j int) bool {
		return groups[i].Count > groups[j].Count
	})
	return groups
}

func (n *node) collect(groups *[]LogGroup) {
	if n.group != nil {
		*groups = append(*groups, *n.group)
	}
	for _, child := range n.children {
		child.collect(groups)
	}
}

package miner

import (
	"allon/internal/io"
)

// ReadLines reads all folded lines from a reader.
func ReadLines(r *io.Reader) ([]FoldedLine, error) {
	var lines []FoldedLine
	for {
		fl, err := r.Next()
		if err != nil {
			break
		}
		lines = append(lines, FoldedLine{
			Text:    fl.Text,
			LineNum: fl.LineNum,
		})
	}
	return lines, nil
}

// Mine reads folded lines from a reader, masks them, groups by template,
// and returns the sorted LogGroups.
func Mine(r *io.Reader, depth int) ([]LogGroup, error) {
	lines, err := ReadLines(r)
	if err != nil {
		return nil, err
	}
	return GroupByTemplate(lines, depth), nil
}

package miner

import (
	"regexp"
)

// typedPlaceholder returns the placeholder token for a recognized pattern.
func typedPlaceholder(s string) string {
	if isUUID(s) {
		return "<UUID>"
	}
	if isIP(s) {
		return "<IP>"
	}
	if isHex(s) {
		return "<HEX>"
	}
	if isNum(s) {
		return "<NUM>"
	}
	if isPath(s) {
		return "<PATH>"
	}
	return ""
}

// isNum reports whether s looks like an integer or decimal number.
func isNum(s string) bool {
	if len(s) == 0 {
		return false
	}
	dotSeen := false
	for _, c := range s {
		switch {
		case c >= '0' && c <= '9':
			continue
		case c == '.' && !dotSeen:
			dotSeen = true
		case c == '-' && len(s) > 1 && s[0] == '-':
			continue
		default:
			return false
		}
	}
	return true
}

// isUUID reports whether s matches the canonical UUID format.
func isUUID(s string) bool {
	if len(s) != 36 {
		return false
	}
	uuidRe := regexp.MustCompile(`^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$`)
	return uuidRe.MatchString(s)
}

// isIP reports whether s looks like an IPv4 address.
func isIP(s string) bool {
	parts := splitRune(s, '.')
	if len(parts) != 4 {
		return false
	}
	for _, p := range parts {
		if !isNum(p) {
			return false
		}
		n := atoi(p)
		if n < 0 || n > 255 {
			return false
		}
	}
	return true
}

// isHex reports whether s is a hex string of length >= 8 (no leading 0x).
func isHex(s string) bool {
	if len(s) < 8 {
		return false
	}
	hexRe := regexp.MustCompile(`^[0-9a-fA-F]+$`)
	return hexRe.MatchString(s)
}

// isPath reports whether s looks like a filesystem path (starts with / or .).
func isPath(s string) bool {
	if len(s) == 0 {
		return false
	}
	return s[0] == '/' || (len(s) >= 2 && s[0] == '.' && s[1] == '/')
}

// MaskLine replaces variable tokens in a log line with typed placeholders.
func MaskLine(line string) string {
	tokens := tokenize(line)
	var result []string
	for _, tok := range tokens {
		if ph := typedPlaceholder(tok); ph != "" {
			result = append(result, ph)
		} else {
			result = append(result, tok)
		}
	}
	return joinTokens(result)
}

// tokenize splits a line on whitespace into tokens.
func tokenize(line string) []string {
	var tokens []string
	var cur []rune
	for _, r := range line {
		switch {
		case r == ' ' || r == '\t':
			if len(cur) > 0 {
				tokens = append(tokens, string(cur))
				cur = cur[:0]
			}
		default:
			cur = append(cur, r)
		}
	}
	if len(cur) > 0 {
		tokens = append(tokens, string(cur))
	}
	return tokens
}

// joinTokens joins tokens back with single spaces.
func joinTokens(tokens []string) string {
	var result []byte
	for i, tok := range tokens {
		if i > 0 {
			result = append(result, ' ')
		}
		result = append(result, tok...)
	}
	return string(result)
}

func lineFromTokens(tokens []string) int {
	l := 0
	for _, t := range tokens {
		l += len(t) + 1
	}
	return l
}

func splitRune(s string, sep rune) []string {
	var parts []string
	var cur []rune
	for _, r := range s {
		if r == sep {
			parts = append(parts, string(cur))
			cur = cur[:0]
		} else {
			cur = append(cur, r)
		}
	}
	parts = append(parts, string(cur))
	return parts
}

func atoi(s string) int {
	var n int
	for _, c := range s {
		if c >= '0' && c <= '9' {
			n = n*10 + int(c-'0')
		}
	}
	return n
}

package miner

// Diff compares two sets of LogGroups and returns NEW, GONE, and SHIFTED entries.
// Identity is a strict hash of the exact token sequence; <*> at any position breaks equality.
func Diff(baseline, current []LogGroup) (newT, goneT, shiftedT []DiffEntry) {
	bMap := make(map[string]*LogGroup)
	for _, g := range baseline {
		h := templateHash(g.Template)
		bMap[h] = &g
	}

	cMap := make(map[string]*LogGroup)
	for _, g := range current {
		h := templateHash(g.Template)
		cMap[h] = &g
	}

	// NEW: in current but not baseline
	for h, cg := range cMap {
		if _, ok := bMap[h]; !ok {
			newT = append(newT, DiffEntry{
				Template:  cg.Template,
				Count:     cg.Count,
				Example:   cg.Example,
				FirstLine: cg.FirstLine,
				LastLine:  cg.LastLine,
			})
		}
	}

	// GONE: in baseline but not current
	for h, bg := range bMap {
		if _, ok := cMap[h]; !ok {
			goneT = append(goneT, DiffEntry{
				Template:  bg.Template,
				Count:     bg.Count,
				Example:   bg.Example,
				FirstLine: bg.FirstLine,
				LastLine:  bg.LastLine,
			})
		}
	}

	// SHIFTED: in both but count changed
	for h, bg := range bMap {
		cg, ok := cMap[h]
		if !ok {
			continue
		}
		if bg.Count != cg.Count {
			shiftedT = append(shiftedT, DiffEntry{
				Template:      bg.Template,
				BaselineCount: bg.Count,
				NewCount:      cg.Count,
			})
		}
	}

	return newT, goneT, shiftedT
}

package miner

import (
	"sort"
)

// GroupByTemplate groups folded lines by their masked template.
// It returns a slice of LogGroup sorted by count descending.
func GroupByTemplate(lines []FoldedLine, depth int) []LogGroup {
	tree := NewTreeFunc(depth)
	for _, fl := range lines {
		masked := MaskLine(fl.Text)
		tree.Insert(masked, fl.Text, int64(fl.LineNum))
	}
	return tree.Collect()
}

// FoldedLine is an alias for the reader's type so we can group without importing io.
type FoldedLine struct {
	Text    string
	LineNum int
}

// SortByCount sorts groups by count descending (in place).
func SortByCount(groups []LogGroup) {
	sort.Slice(groups, func(i, j int) bool {
		return groups[i].Count > groups[j].Count
	})
}

package miner

import (
	"testing"
)

func TestDiff_New(t *testing.T) {
	baseline := []LogGroup{
		{Template: "error occurred", Count: 5, Example: "error occurred", FirstLine: 1, LastLine: 5},
	}
	current := []LogGroup{
		{Template: "error occurred", Count: 5, Example: "error occurred", FirstLine: 1, LastLine: 5},
		{Template: "new template", Count: 3, Example: "new template", FirstLine: 6, LastLine: 8},
	}
	newT, goneT, shiftedT := Diff(baseline, current)
	if len(newT) != 1 {
		t.Fatalf("expected 1 new, got %d", len(newT))
	}
	if newT[0].Template != "new template" {
		t.Errorf("got %q", newT[0].Template)
	}
	if len(goneT) != 0 {
		t.Errorf("expected 0 gone, got %d", len(goneT))
	}
	if len(shiftedT) != 0 {
		t.Errorf("expected 0 shifted, got %d", len(shiftedT))
	}
}

func TestDiff_Gone(t *testing.T) {
	baseline := []LogGroup{
		{Template: "old template", Count: 2, Example: "old template", FirstLine: 1, LastLine: 2},
	}
	current := []LogGroup{}
	newT, goneT, _ := Diff(baseline, current)
	if len(newT) != 0 {
		t.Errorf("expected 0 new, got %d", len(newT))
	}
	if len(goneT) != 1 {
		t.Fatalf("expected 1 gone, got %d", len(goneT))
	}
	if goneT[0].Template != "old template" {
		t.Errorf("got %q", goneT[0].Template)
	}
}

func TestDiff_Shifted(t *testing.T) {
	baseline := []LogGroup{
		{Template: "error occurred", Count: 5, Example: "error occurred", FirstLine: 1, LastLine: 5},
	}
	current := []LogGroup{
		{Template: "error occurred", Count: 10, Example: "error occurred", FirstLine: 1, LastLine: 10},
	}
	newT, goneT, shiftedT := Diff(baseline, current)
	if len(newT) != 0 {
		t.Errorf("expected 0 new, got %d", len(newT))
	}
	if len(goneT) != 0 {
		t.Errorf("expected 0 gone, got %d", len(goneT))
	}
	if len(shiftedT) != 1 {
		t.Fatalf("expected 1 shifted, got %d", len(shiftedT))
	}
	if shiftedT[0].BaselineCount != 5 || shiftedT[0].NewCount != 10 {
		t.Errorf("expected baseline=5 new=10, got %d/%d", shiftedT[0].BaselineCount, shiftedT[0].NewCount)
	}
}

func TestDiff_StrictHash_WildcardBreaksEquality(t *testing.T) {
	// <*> at any position breaks equality: "error <*> occurred" != "error <NUM> occurred"
	baseline := []LogGroup{
		{Template: "error <*> occurred", Count: 1, Example: "e", FirstLine: 1, LastLine: 1},
	}
	current := []LogGroup{
		{Template: "error <NUM> occurred", Count: 1, Example: "e", FirstLine: 1, LastLine: 1},
	}
	newT, goneT, shiftedT := Diff(baseline, current)
	// They have different hashes so baseline is GONE and current is NEW
	if len(goneT) != 1 {
		t.Errorf("expected 1 gone, got %d", len(goneT))
	}
	if len(newT) != 1 {
		t.Errorf("expected 1 new, got %d", len(newT))
	}
	if len(shiftedT) != 0 {
		t.Errorf("expected 0 shifted (wildcards break equality), got %d", len(shiftedT))
	}
}

