func TestTreeFixedDepth(t *testing.T) {
	tree := NewTreeFunc(2)
	tree.Insert("error 1 in module", "error 1 in module", 1)
	tree.Insert("error 2 in module", "error 2 in module", 2)
	groups := tree.Collect()
	if len(groups) != 1 {
		t.Fatalf("expected 1 group, got %d", len(groups))
	}
	if groups[0].Template != "error <*> <*>" {
		t.Errorf("got %q", groups[0].Template)
	}
