		t.Errorf("expected count 2, got %d", groups[0].Count)
	}
}

func TestGroupByTemplate(t *testing.T) {
	lines := []FoldedLine{
		{Text: "error 1 occurred", LineNum: 1},
		{Text: "error 2 occurred", LineNum: 2},
		{Text: "success", LineNum: 3},
	}
	groups := GroupByTemplate(lines, -1)
	if len(groups) != 2 {
		t.Fatalf("expected 2 groups, got %d", len(groups))
	}
	// Both error lines mask to same template
	if groups[0].Count != 2 {
		t.Errorf("expected count 2, got %d", groups[0].Count)
	}
	if groups[0].Template != "error <NUM> occurred" {
		t.Errorf("got %q", groups[0].Template)
	}
}
